//! pair_visual_wiring.rs — PC-K1: connects the K1 pair visual read layer into
//! the real engine input/output chain.
//!
//! STATUS: new file, add-only. No existing file is modified and no existing
//! behaviour changes: this module is not referenced by any existing module,
//! so the chain below runs only when the caller opts in by calling
//! `read_kerning_folder` (chief architect registers the module and wires the
//! run flag; default OFF).
//!
//! The gap this closes: pipeline/src/kerning_pairs.rs (input: sha-pinned
//! kerning-folder inventory, bounded decode, ink extent) dropped the decoded
//! raster and never called the measurement layer; metrics/src/pair_visual_read.rs
//! (read_pair_image: pixel-derived inter-glyph gap, typed refusals) had zero
//! callers in pipeline/src or core/src. This file is the missing link:
//!
//!   kerning folder (real members, sha-pinned names)
//!     -> kerning_pairs::inventory        (input chain, whole-folder typed refusals)
//!     -> kerning_pairs::resolve_roles    (alias receipt / typed ambiguity refusal)
//!     -> kni_core::capture_dispatch::decode_source (same bounded decoder the
//!        input chain's measure_ink uses; the raster is kept, that is the fix)
//!     -> kni_metrics::pair_visual_read::read_pair_image (K1 measurement)
//!     -> PairReportRow rows + report_tsv (output: measured and typed-failed
//!        rows; no row is ever silently skipped)
//!
//! Kerning STRING images (3+ codepoints) are not pairs: they are receipted in
//! `non_pair_images` with their sha256, never measured as pairs and never
//! dropped silently. Measurement layer only: nothing here proposes, ships, or
//! overrides a kern value, and nothing is copied from a source font's tables.

use kni_core::capture::DecodeLimits;
use kni_core::cff_reader::sha256_hex;
use kni_metrics::pair_visual_read::{
    report_summary, report_tsv, GrayImage, PairReportRow,
};
use std::path::Path;

use crate::kerning_pairs::{
    inventory, read_capped, ImageExt, InventoryBudget, KernImageEntry, KernPairError,
};
use std::collections::{BTreeMap, BTreeSet};

/// Explicit inputs for one opt-in folder read. All budgets are caller-supplied;
/// nothing is defaulted inside the wiring.
#[derive(Debug, Clone)]
pub struct PairVisualWiring {
    /// Folder inventory budget (members, per-member bytes, total bytes).
    pub inventory: InventoryBudget,
    /// Per-member byte cap for the decode re-read (sha re-pinned before decode).
    pub max_member_bytes: u64,
    /// Bounded PNG decode limits (the same struct the input chain passes).
    pub decode: DecodeLimits,
    /// Bounded JPEG decode limits (only used for .jpg/.jpeg members).
    pub jpeg: kni_core::jpeg_source::Limits,
    /// Font units per source pixel, when a font-unit reading is wanted.
    pub scale_fu_per_px: Option<f64>,
}

/// Receipt for a resolved kerning member that is not a 2-codepoint pair
/// (a kerning STRING image): kept visible, never measured as a pair.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NonPairReceipt {
    pub seq: Vec<u32>,
    pub index: u32,
    pub sha256: String,
}

/// Outcome of one opt-in folder read: every resolved member appears exactly
/// once, as a measured row, a typed failure row, or a non-pair receipt.
pub struct PairVisualOutcome {
    #[allow(dead_code)] // read by unit tests; production output is report_tsv
    pub rows: Vec<PairReportRow>,
    /// (measured, refused) over `rows`, from the measurement layer's summary.
    pub measured: usize,
    pub refused: usize,
    /// Rows whose pixels never reached the measurement layer (decode/read
    /// failure): the "unavailable" third state next to measured and failed
    /// (measurement refusals). unavailable <= refused; refused - unavailable
    /// is the measurement-refusal count.
    pub unavailable: usize,
    /// Alias receipts from resolve_roles: identical content under another name.
    pub aliases: Vec<(Vec<u32>, u32, u32, String)>,
    pub non_pair_images: Vec<NonPairReceipt>,
    /// Fixed-header TSV (measured rows carry numbers; refused rows carry the
    /// typed reason). Ready to write as the run's pair-visual report artifact.
    pub tsv: String,
}

/// Glyph label for one codepoint: the character itself when it is a valid
/// Unicode scalar value, otherwise its U+XXXX form. Deterministic; no glyph
/// vocabulary is invented.
fn cp_label(cp: u32) -> String {
    char::from_u32(cp).map(|c| c.to_string()).unwrap_or_else(|| format!("U+{cp:04X}"))
}

/// Bounded decode of one sha-pinned member into a gray raster. Mirrors the
/// exact safety steps of kerning_pairs::measure_ink (cap-bounded read, sha
/// re-pin, extension/signature check, capture_dispatch) but keeps the raster,
/// which the ingestion layer discards; that discard is the gap this wiring closes.
fn decode_entry(
    entry: &KernImageEntry,
    max_bytes: u64,
    limits: &DecodeLimits,
    jpeg: kni_core::jpeg_source::Limits,
) -> Result<GrayImage, KernPairError> {
    let file = entry.path().display().to_string();
    let bytes = read_capped(entry.path(), max_bytes)?;
    let actual = sha256_hex(&bytes);
    if actual != entry.sha256() {
        return Err(KernPairError::ShaMismatch {
            file,
            name_prefix: entry.sha256().get(..12).unwrap_or("").into(),
            actual,
        });
    }
    let is_png = bytes.starts_with(b"\x89PNG\r\n\x1a\n");
    if is_png != (entry.ext() == ImageExt::Png) {
        return Err(KernPairError::ExtensionSignatureMismatch(file));
    }
    let d = kni_core::capture_dispatch::decode_source(&bytes, limits, jpeg)
        .map_err(|e| KernPairError::Decode { file: file.clone(), why: format!("{e:?}") })?;
    Ok(GrayImage { width: d.width, height: d.height, gray: d.gray })
}

/// Per-item role resolution: the exact refusal rules of
/// kerning_pairs::resolve_roles (identical content under one role = alias with
/// receipt; different content under one role = ambiguous; same content under
/// two roles = conflict) applied at per-item granularity, so one ambiguous
/// member can never kill the batch (owner rule K5: a batch reports per-item
/// typed failures and dies only when nothing is exportable). Real kernband
/// folders alias typographically identical glyphs (comma vs single low-quote,
/// eth vs d-stroke): under whole-folder refusal the measurement layer would be
/// unreachable on every real folder. Conflicted or ambiguous members become
/// typed `PairReportRow::Failed` rows carrying the full conflict evidence
/// (owner rule F15: no exclusion without evidence); the rest resolve and
/// measure. resolve_roles itself is untouched: existing callers keep
/// whole-folder semantics.
struct PerItemResolution {
    roles: BTreeMap<Vec<u32>, KernImageEntry>,
    aliases: Vec<(Vec<u32>, u32, u32, String)>,
    quarantined: Vec<PairReportRow>,
}

fn role_labels(seq: &[u32]) -> (String, String) {
    (
        seq.first().map(|&c| cp_label(c)).unwrap_or_default(),
        seq.get(1).map(|&c| cp_label(c)).unwrap_or_default(),
    )
}

fn resolve_roles_per_item(entries: &[KernImageEntry]) -> PerItemResolution {
    // Same image content under two DIFFERENT roles: the name does not say what
    // the image is. Every role carrying that content is quarantined with the
    // evidence, never guessed (resolve_roles' ContentConflict, per item).
    let mut by_sha: BTreeMap<&str, BTreeSet<&[u32]>> = BTreeMap::new();
    for e in entries {
        by_sha.entry(e.sha256()).or_default().insert(e.seq());
    }
    let conflicted: BTreeSet<&str> = by_sha
        .iter()
        .filter(|(_, seqs)| seqs.len() > 1)
        .map(|(sha, _)| *sha)
        .collect();
    let mut quarantined: Vec<PairReportRow> = Vec::new();
    for sha in &conflicted {
        let seqs: Vec<String> = by_sha[sha]
            .iter()
            .map(|s| s.iter().map(|c| format!("U+{c:04X}")).collect::<Vec<_>>().join("_"))
            .collect();
        let why = format!(
            "content conflict: identical image bytes (sha256 {sha}) serve roles [{}]; the source does not determine which one is the evidence",
            seqs.join(", ")
        );
        let mut seen: BTreeSet<&[u32]> = BTreeSet::new();
        for e in entries.iter().filter(|e| e.sha256() == *sha) {
            if seen.insert(e.seq()) {
                let (left, right) = role_labels(e.seq());
                quarantined.push(PairReportRow::Failed {
                    left,
                    right,
                    image_path: e.path().display().to_string(),
                    source_sha256: Some(e.sha256().to_string()),
                    error: why.clone(),
                });
            }
        }
    }
    // Per role: one distinct content = resolved (lowest index kept, the rest
    // alias-receipted); several distinct contents = ambiguous, quarantined with
    // the candidate shas (resolve_roles' AmbiguousRole, per item; never
    // first-wins, never newest-wins).
    let mut by_seq: BTreeMap<&[u32], Vec<&KernImageEntry>> = BTreeMap::new();
    for e in entries.iter().filter(|e| !conflicted.contains(e.sha256())) {
        by_seq.entry(e.seq()).or_default().push(e);
    }
    let mut roles: BTreeMap<Vec<u32>, KernImageEntry> = BTreeMap::new();
    let mut aliases: Vec<(Vec<u32>, u32, u32, String)> = Vec::new();
    for (seq, mut v) in by_seq {
        v.sort_by_key(|e| (e.index(), e.path().to_path_buf()));
        let shas: BTreeSet<&str> = v.iter().map(|e| e.sha256()).collect();
        if shas.len() != 1 {
            let (left, right) = role_labels(seq);
            quarantined.push(PairReportRow::Failed {
                left,
                right,
                image_path: v[0].path().display().to_string(),
                source_sha256: None,
                error: format!(
                    "ambiguous role: {} different images (sha256 [{}]) claim the same role; the source does not determine which one is the evidence",
                    shas.len(),
                    shas.into_iter().collect::<Vec<_>>().join(", ")
                ),
            });
            continue;
        }
        for dup in &v[1..] {
            aliases.push((seq.to_vec(), v[0].index(), dup.index(), dup.sha256().to_string()));
        }
        roles.insert(seq.to_vec(), v[0].clone());
    }
    PerItemResolution { roles, aliases, quarantined }
}

/// Opt-in end-to-end read of one `<Family>/<Style>/kerning/` folder.
///
/// Whole-folder violations (bad name, sha mismatch, budget exceeded, ambiguous
/// role, content conflict, ...) refuse the read with the input chain's own
/// typed `KernPairError` — no partial results. Per-pair decode or measurement
/// failures become typed `PairReportRow::Failed` rows with the member's
/// provenance; the batch never dies on one member's failure.
pub fn read_kerning_folder(
    dir: &Path,
    w: &PairVisualWiring,
) -> Result<PairVisualOutcome, KernPairError> {
    let entries = inventory(dir, &w.inventory)?;
    let resolved = resolve_roles_per_item(&entries);
    let mut rows: Vec<PairReportRow> = resolved.quarantined;
    let mut non_pair: Vec<NonPairReceipt> = Vec::new();
    for (seq, entry) in &resolved.roles {
        let Some((l, r)) = entry.pair() else {
            non_pair.push(NonPairReceipt {
                seq: seq.clone(),
                index: entry.index(),
                sha256: entry.sha256().to_string(),
            });
            continue;
        };
        let (left, right) = (cp_label(l), cp_label(r));
        match decode_entry(entry, w.max_member_bytes, &w.decode, w.jpeg) {
            Ok(img) => {
                match kni_metrics::pair_visual_read::read_pair_image(
                    &left,
                    &right,
                    &img,
                    entry.sha256(),
                    w.scale_fu_per_px,
                ) {
                    Ok(m) => rows.push(PairReportRow::Measured(m)),
                    Err(e) => rows.push(PairReportRow::Failed {
                        left,
                        right,
                        image_path: entry.path().display().to_string(),
                        source_sha256: Some(entry.sha256().to_string()),
                        error: e.to_string(),
                    }),
                }
            }
            Err(e) => rows.push(PairReportRow::Failed {
                left,
                right,
                image_path: entry.path().display().to_string(),
                source_sha256: None,
                error: format!("unavailable: decode {e:?}"),
            }),
        }
    }
    let (measured, refused) = report_summary(&rows);
    let unavailable = rows
        .iter()
        .filter(|r| matches!(r, PairReportRow::Failed { error, .. } if error.starts_with("unavailable: ")))
        .count();
    let tsv = report_tsv(&rows);
    Ok(PairVisualOutcome {
        rows,
        measured,
        refused,
        unavailable,
        aliases: resolved.aliases,
        non_pair_images: non_pair,
        tsv,
    })
}

#[cfg(test)]
pub(crate) mod tests {
    use super::*;
    use std::path::PathBuf;

    // Real fixtures (PC-K1): members of the karlnawrot kernband tar whose
    // sha256 is pinned by kni-kit/collection/_merge-provenance/kernband-space-
    // 20261012/SOURCE.txt (59432960 bytes, sha256 5530ba71d47754b8172c5f27b4
    // 24d9c8d2def76020aef730e48120a098e96f57); every member's own sha256 is
    // pinned by that merge's MANIFEST.tsv. Base64 of the exact member bytes:
    //   I_HYPHEN:  Lÿno/Walt/kerning/00224__0049_002D__caa217c13292.png
    //              sha256 caa217c13292e7af918619f777dadb6b24ab1e031c2e3543c508cf90721a4d56 (7106 bytes)
    //   H_UNDER:   Lÿno/Walt/kerning/00221__0048_005F__f396cb2787c6.png
    //              sha256 f396cb2787c6667c92e4becb16e752492b21eecf37e3ba9452dc563f8713999c (11520 bytes)
    //   B_ETH/B_DSTROKE: Unit/Regular/kerning/00368__0042_00D0__ae3d00adbd83.png
    //              and 00369__0042_0110__ae3d00adbd83.png: identical bytes
    //              (real typographic alias), sha256 ae3d00adbd83b975ef60b3ba665c079292d0b74cf3d61b04385ff7088b9ec2e36f (17453 bytes)
    pub(crate) const I_HYPHEN_B64: &str = "";
    pub(crate) const H_UNDER_B64: &str = "";
    pub(crate) const B_ALIAS_B64: &str = "";

    pub(crate) fn b64decode(s: &str) -> Vec<u8> {
        fn v(b: u8) -> u8 {
            match b {
                b'A'..=b'Z' => b - b'A',
                b'a'..=b'z' => b - b'a' + 26,
                b'0'..=b'9' => b - b'0' + 52,
                b'+' => 62,
                b'/' => 63,
                _ => panic!("bad base64"),
            }
        }
        let mut out = Vec::with_capacity(s.len() * 3 / 4);
        let mut acc: u32 = 0;
        let mut n = 0;
        for &b in s.as_bytes() {
            if b == b'=' { break; }
            acc = (acc << 6) | v(b) as u32;
            n += 1;
            if n == 4 {
                out.push((acc >> 16) as u8);
                out.push((acc >> 8) as u8);
                out.push(acc as u8);
                acc = 0;
                n = 0;
            }
        }
        match n {
            0 => {}
            2 => out.push((acc >> 4) as u8),
            3 => {
                out.push((acc >> 10) as u8);
                out.push((acc >> 2) as u8);
            }
            _ => panic!("bad base64 length"),
        }
        out
    }

    pub(crate) fn tmp(tag: &str) -> PathBuf {
        let d = std::env::temp_dir().join(format!("pvw-{tag}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&d);
        std::fs::create_dir_all(&d).unwrap();
        d
    }

    /// Write `bytes` under a real-grammar, sha-consistent member name.
    pub(crate) fn put(d: &Path, index: u32, seq: &[u32], bytes: &[u8]) {
        let sha = kni_core::cff_reader::sha256_hex(bytes);
        let cps: Vec<String> = seq.iter().map(|c| format!("{c:04X}")).collect();
        std::fs::write(d.join(format!("{index:05}__{}__{}.png", cps.join("_"), &sha[..12])), bytes).unwrap();
    }

    pub(crate) fn wiring() -> PairVisualWiring {
        PairVisualWiring {
            inventory: InventoryBudget { max_members: 100, max_member_bytes: 1 << 20, max_total_bytes: 1 << 24 },
            max_member_bytes: 1 << 20,
            decode: DecodeLimits { max_input_bytes: 1 << 20, max_pixels: 1 << 22, max_working_bytes: 1 << 26 },
            jpeg: kni_core::jpeg_source::Limits { max_input_bytes: 1 << 20, max_pixels: 1 << 22, max_working_bytes: 1 << 26 },
            scale_fu_per_px: None,
        }
    }

    #[test]
    fn real_fixtures_end_to_end_measured_failed_and_conflict() {
        let d = tmp("e2e");
        put(&d, 224, &[0x49, 0x2D], &b64decode(I_HYPHEN_B64));
        put(&d, 221, &[0x48, 0x5F], &b64decode(H_UNDER_B64));
        put(&d, 368, &[0x42, 0xD0], &b64decode(B_ALIAS_B64));
        put(&d, 369, &[0x42, 0x110], &b64decode(B_ALIAS_B64));
        let out = read_kerning_folder(&d, &wiring()).unwrap();
        // every member surfaces exactly once: 4 rows, no silent skips
        assert_eq!(out.rows.len(), 4);
        assert_eq!((out.measured, out.refused, out.unavailable), (1, 3, 0));
        assert!(out.aliases.is_empty() && out.non_pair_images.is_empty());
        // I-hyphen: real measured values, pinned from the real file
        let m = out.rows.iter().find_map(|r| match r {
            PairReportRow::Measured(m) => Some(m),
            _ => None,
        }).expect("one measured row");
        assert_eq!((m.left.as_str(), m.right.as_str()), ("I", "-"));
        assert_eq!(m.source_sha256, "caa217c13292e7af918619f777dadb6b24ab1e031c2e3543c508cf90721a4d56");
        assert_eq!((m.min_gap_px, m.mean_gap_px, m.shared_rows), (20.0, 20.0, 62));
        assert_eq!(m.gap_band, (689, 709));
        assert!(m.gap_fu.is_none()); // no caller scale: pixels only, documented
        // H-underscore: real measurement refusal (touching members)
        assert!(out.rows.iter().any(|r| matches!(r, PairReportRow::Failed { left, right, error, source_sha256, .. }
            if left == "H" && right == "_" && error.contains("no usable zero-ink column band")
              && source_sha256.as_deref() == Some("f396cb2787c6667c92e4becb16e752492b21eecf37e3ba9452dc563f8713999c"))));
        // The typographic alias pair: BOTH roles quarantined with the full
        // conflict evidence; neither is guessed.
        for (l, r) in [("B", "Ð"), ("B", "Đ")] {
            assert!(out.rows.iter().any(|row| matches!(row, PairReportRow::Failed { left, right, error, .. }
                if left == l && right == r
                  && error.contains("content conflict") && error.contains("U+0042_U+00D0") && error.contains("U+0042_U+0110"))), "{l}{r}");
        }
        // TSV: header + one line per member
        assert_eq!(out.tsv.lines().count(), 5);
        let _ = std::fs::remove_dir_all(d);
    }

    #[test]
    fn sha_mismatch_refuses_the_whole_folder_typed() {
        let d = tmp("sha");
        let mut bad = b64decode(I_HYPHEN_B64);
        let n = bad.len();
        bad[n - 1] ^= 0xFF; // content no longer matches the name's sha pin
        put(&d, 224, &[0x49, 0x2D], &bad); // `put` re-pins honestly; write the lie by hand instead
        // rewrite with the ORIGINAL name so the pin lies:
        let lie = d.join("00224__0049_002D__caa217c13292.png");
        std::fs::write(&lie, &bad).unwrap();
        // the honestly-pinned duplicate from `put` must not exist for this check
        for e in std::fs::read_dir(&d).unwrap() {
            let p = e.unwrap().path();
            if p != lie { std::fs::remove_file(p).unwrap(); }
        }
        assert!(matches!(read_kerning_folder(&d, &wiring()), Err(KernPairError::ShaMismatch { .. })));
        let _ = std::fs::remove_dir_all(d);
    }

    #[test]
    fn alias_is_deduplicated_with_receipt() {
        let d = tmp("alias");
        let bytes = b64decode(I_HYPHEN_B64);
        put(&d, 226, &[0x49, 0x2D], &bytes);
        put(&d, 224, &[0x49, 0x2D], &bytes); // same content, lower index wins
        let out = read_kerning_folder(&d, &wiring()).unwrap();
        assert_eq!((out.measured, out.refused), (1, 0));
        assert_eq!(out.aliases, vec![(vec![0x49, 0x2D], 224, 226, "caa217c13292e7af918619f777dadb6b24ab1e031c2e3543c508cf90721a4d56".to_string())]);
        let _ = std::fs::remove_dir_all(d);
    }

    #[test]
    fn ambiguous_role_is_a_typed_row_and_the_batch_survives() {
        let d = tmp("amb");
        put(&d, 221, &[0x48, 0x5F], &b64decode(H_UNDER_B64)); // unaffected member still flows
        put(&d, 224, &[0x49, 0x2D], &b64decode(I_HYPHEN_B64));
        put(&d, 225, &[0x49, 0x2D], b"synthetic second content claiming the same role (PC-K1 test)");
        let out = read_kerning_folder(&d, &wiring()).unwrap();
        // the ambiguous role collapses to ONE typed row (both claimants refused
        // together); the unaffected member still flows: 2 rows, nothing skipped
        assert_eq!(out.rows.len(), 2);
        assert!(out.rows.iter().any(|r| matches!(r, PairReportRow::Failed { left, right, error, .. }
            if left == "I" && right == "-" && error.contains("ambiguous role")
              && error.contains("caa217c13292e7af918619f777dadb6b24ab1e031c2e3543c508cf90721a4d56"))));
        // the unaffected member is still processed (typed refusal, real reason)
        assert!(out.rows.iter().any(|r| matches!(r, PairReportRow::Failed { left, error, .. }
            if left == "H" && error.contains("no usable zero-ink column band"))));
        let _ = std::fs::remove_dir_all(d);
    }

    #[test]
    fn decode_failure_is_unavailable_third_state_batch_survives() {
        let d = tmp("unavail");
        put(&d, 224, &[0x49, 0x2D], &b64decode(I_HYPHEN_B64)); // still measured
        // passes the name pin and the signature check, then dies in decode
        put(&d, 300, &[0x41, 0x56], b"\x89PNG\r\n\x1a\ntruncated-garbage-not-a-png-body");
        let out = read_kerning_folder(&d, &wiring()).unwrap();
        assert_eq!((out.rows.len(), out.measured), (2, 1));
        assert_eq!(out.unavailable, 1);
        assert!(out.rows.iter().any(|r| matches!(r, PairReportRow::Failed { left, right, error, .. }
            if left == "A" && right == "V" && error.starts_with("unavailable: decode "))));
        let _ = std::fs::remove_dir_all(d);
    }

    #[test]
    fn kerning_string_images_are_receipted_never_measured_as_pairs() {
        let d = tmp("str");
        put(&d, 224, &[0x49, 0x2D], &b64decode(I_HYPHEN_B64));
        put(&d, 187, &[0x66, 0x2E, 0x201D], b"synthetic 3-codepoint string image (PC-K1 test)");
        let out = read_kerning_folder(&d, &wiring()).unwrap();
        assert_eq!((out.measured, out.rows.len()), (1, 1));
        assert_eq!(out.non_pair_images.len(), 1);
        assert_eq!(out.non_pair_images[0].seq, vec![0x66, 0x2E, 0x201D]);
        assert_eq!(out.non_pair_images[0].index, 187);
        let _ = std::fs::remove_dir_all(d);
    }
}
